        "details": "Create the routes and API endpoints for the application with the following:

1. Main UI route
2. API endpoints for directory scanning, image listing, thumbnails, tags, and rename operations
3. Error handling for all routes
4. JSON responses for API endpoints

Implementation details:
```python
from flask import Flask, render_template, request, jsonify, send_file, abort
import os
from pathlib import Path
import logging

from models.file_manager import scan_directory, rename_file
from models.tag_manager import TagManager
from thumbnail import generate_thumbnail

app = Flask(__name__)
tag_manager = TagManager()

# Configure logging
logging.basicConfig(filename='~/.image-tagger-renamer/app.log', level=logging.INFO,
                   format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

@app.route('/')
def index():
    """Render the main application UI"""
    return render_template('index.html')

@app.route('/api/images')
def get_images():
    """Get all images in the specified directory with thumbnails"""
    directory = request.args.get('dir')
    if not directory:
        return jsonify({'error': 'No directory specified'}), 400

    try:
        image_files = scan_directory(directory)
        images = []

        for img_path in image_files:
            try:
                # Generate thumbnail and get URL
                thumbnail = generate_thumbnail(img_path)

                images.append({
                    'path': str(img_path),
                    'name': img_path.name,
                    'thumbnail': f'/api/thumbnail?path={str(thumbnail)}'
                })
            except Exception as e:
                logger.error(f"Error processing image {img_path}: {str(e)}")

        return jsonify({
            'directory': directory,
            'count': len(images),
            'images': images
        })
    except Exception as e:
        logger.error(f"Error scanning directory {directory}: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/thumbnail')
def get_thumbnail():
    """Serve a cached thumbnail"""
    path = request.args.get('path')
    if not path or not os.path.exists(path):
        abort(404)

    return send_file(path)

@app.route('/api/tags', methods=['GET'])
def get_tags():
    """Get all available tags"""
    return jsonify({'tags': tag_manager.get_all_tags()})

@app.route('/api/tags', methods=['POST'])
def add_tag():
    """Add a new tag"""
    data = request.json
    if not data or 'tag' not in data:
        return jsonify({'error': 'No tag specified'}), 400

    success, message = tag_manager.add_tag(data['tag'])
    if success:
        return jsonify({'status': 'success', 'message': message})
    else:
        return jsonify({'error': message}), 400

@app.route('/api/rename', methods=['POST'])
def rename_images():
    """Rename selected images"""
    data = request.json
    if not data or 'images' not in data or 'tags' not in data:
        return jsonify({'error': 'Missing required parameters'}), 400

    images = data['images']
    tags = data['tags']
    prefix = data.get('prefix', '')
    suffix = data.get('suffix', '')

    results = []
    for img_path in images:
        try:
            new_name, error = rename_file(
                img_path, 
                Path(img_path).parent,
                prefix, 
                tags, 
                suffix
            )

            results.append({
                'original': img_path,
                'new_name': new_name,
                'success': error is None,
                'error': error
            })

            if error:
                logger.error(f"Error renaming {img_path}: {error}")
            else:
                logger.info(f"Renamed {img_path} to {new_name}")

        except Exception as e:
            logger.error(f"Exception renaming {img_path}: {str(e)}")
            results.append({
                'original': img_path,
                'success': False,
                'error': str(e)
            })

    return jsonify({
        'results': results,
        'success_count': sum(1 for r in results if r['success']),
        'error_count': sum(1 for r in results if not r['success'])
    })

if __name__ == '__main__':
    app.run(debug=True)
```",

